BEGIN;

CREATE TABLE IF NOT EXISTS compliance_requirements_archive_m820_c4p AS SELECT * FROM compliance_requirements WHERE false;
CREATE TABLE IF NOT EXISTS fields_archive_m820_c4p AS SELECT * FROM fields WHERE false;
CREATE TABLE IF NOT EXISTS m820_c4p_written (tbl text NOT NULL, id uuid NOT NULL, md5 text NOT NULL, PRIMARY KEY (tbl, id));

-- ── A · three NEW phase drivers (C-9 pattern of 20261008100000: boolean, required, section B, order 0; inserted only when the symbol is absent
--       on the sheet; the ledger row 'fields_new' is written only for a row inserted by THIS run, so the rollback never deletes a row it did not create) ──
-- NEW DWA-M-820-2 820-2-09 phase_auftrag_erteilt (boolean, required, section B)
WITH ins AS (
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, visible_when, consumer_worksheets, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'phase_auftrag_erteilt', $m$Auftrag an den Auftragnehmer erteilt (Vertrag geschlossen)$m$, $m$Contract with the planner / engineering office concluded$m$, 'boolean', NULL, true, $m$§2.1, §4.6, §4.7$m$,
       $m$Ja/Nein: Ist der Auftrag an den Auftragnehmer erteilt, also der Vertrag geschlossen? Auftragnehmer im Sinne des Merkblatts – § 2.1 (S. 12): „Auftragnehmer (Planer, Ingenieurbüro)“. Die vier Vertrags- und Qualitätsfragen dieses Blatts setzen diesen Vertrag voraus: Vertragsfortschreibung (contract_amendments_tracked; § 4.6.1 (S. 32 f.): „Ein Vertrag wird geschlossen, bei dem Änderungen nachvollziehbar fortgeschrieben werden, sodass jeder, der in das Projekt einsteigt, klar erkennen kann, was vertraglich vereinbart wurde.“), Freigaben und Abnahmen der Planungsleistungen (approval_procedure_defined; § 4.6.2 (S. 33): „Im Vertrag mit dem Auftragnehmer wird generell festgelegt, dass Teilabnahmen möglich sind.“), Qualitätsüberwachung der Planungsleistung (quality_monitoring_active; § 4.7.1 (S. 34): „Die Qualitätsüberwachung der Planungsleistungen ist vertraglich nicht geregelt.“) und QS-Plan LPH 8 (qs_plan_lph8_present; § 4.7.2 (S. 34): „Im Auftragnehmerteam ist nicht geklärt, nach welchen Vorgaben und in welchem Umfang die Qualitätskontrolle der Bauleistungen erfolgt.“). Nein = Phase noch nicht erreicht: die vier Fragen sind ausgeblendet, REQ-16 bis REQ-19 gelten noch nicht. Ja: die Fragen werden gestellt und REQ-16 bis REQ-19 gelten. Ist der Vertrag geschlossen, die Antwort auf Ja setzen und das Blatt erneut zur Freigabe einreichen. Eine Konformitätserklärung deckt nur die Phasen ab, die hier als erreicht markiert sind. Unbeantwortet bleiben die Fragen sichtbar und REQ-16 wartet (sperrt) und nennt diese Frage. Werkzeug-Frage; Phase im Sinne von DWA-M 820-3 § 2.1 (S. 8): „bestimmter Abschnitt des gesamten Projektablaufs, der einen eindeutigen Beginn und ein definiertes Ende aufweist“. Die Bestätigung zu den HOAI-Grundleistungen (hoai_grundleistungen_limits, § 4.1) bleibt sichtbar.
[EN] Yes/No: is the contract with the planner / engineering office (Auftragnehmer) concluded? Auftragnehmer in the sense of the Merkblatt – § 2.1 (p. 12): "Auftragnehmer (planner, engineering office)". The four contract and quality questions of this sheet presuppose this contract: contract update (contract_amendments_tracked; § 4.6.1 (pp. 32 f.): "a contract is concluded in which changes are traceably updated, so that anyone who joins the project can clearly see what was contractually agreed."), releases and acceptances of the planning services (approval_procedure_defined; § 4.6.2 (p. 33): "in the contract with the Auftragnehmer (planner) it is generally laid down that partial acceptances are possible."), quality monitoring of the planning service (quality_monitoring_active; § 4.7.1 (p. 34): "the quality monitoring of the planning services is not regulated by contract.") and QA plan LPH 8 (qs_plan_lph8_present; § 4.7.2 (p. 34): "in the Auftragnehmer (planner) team it is not clarified according to which specifications and to what extent the quality control of the construction works takes place."). No = phase not reached yet: the four questions are hidden, REQ-16 to REQ-19 do not apply yet. Yes: the questions are asked and REQ-16 to REQ-19 apply. When the contract is concluded, set the answer to Yes and submit the sheet for approval again. A conformity declaration covers only the phases marked as reached here. Unanswered, the questions stay visible and REQ-16 waits (blocks) and names this question. Tool question; phase in the sense of DWA-M 820-3 § 2.1 (p. 8): "a specific section of the entire project sequence that has a clear beginning and a defined end". The acknowledgement on the HOAI basic services (hoai_grundleistungen_limits, § 4.1) stays visible.$m$,
       'imported_unverified', $m$§ 2.1 (S. 12): „Auftragnehmer (Planer, Ingenieurbüro)“ § 4.6.2 (S. 33): „Im Vertrag mit dem Auftragnehmer wird generell festgelegt, dass Teilabnahmen möglich sind.“ § 4.7.1 (S. 34): „Die Qualitätsüberwachung der Planungsleistungen ist vertraglich nicht geregelt.“ DWA-M 820-3 § 2.1 (S. 8): „bestimmter Abschnitt des gesamten Projektablaufs, der einen eindeutigen Beginn und ein definiertes Ende aufweist“$m$, $m$DWA-M 820-2 §2.1 Z.349 (PDF S. 14) + DWA-M 820-2 §4.6.2 Z.931 (PDF S. 35) + DWA-M 820-2 §4.7.1 Z.941 (PDF S. 36) + DWA-M 820-3 §2.1 Z.219 (PDF S. 10)$m$, NULL, NULL, NULL, NULL, 0, true
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE s.code = 'DWA-M-820-2' AND w.code = '820-2-09'
   AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'phase_auftrag_erteilt')
RETURNING *)
INSERT INTO m820_c4p_written (tbl, id, md5) SELECT 'fields_new', ins.id, md5(row_to_json(ins)::text) FROM ins;
-- NEW DWA-M-820-2 820-2-15 phase_planung_abgeschlossen (boolean, required, section B)
WITH ins AS (
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, visible_when, consumer_worksheets, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'phase_planung_abgeschlossen', $m$Phase „Planung“ abgeschlossen (bis zur Erteilung der Genehmigungen)$m$, $m$Phase "planning" completed (up to the granting of the permits)$m$, 'boolean', NULL, true, $m$§5.3; DWA-M 820-3 §6.3$m$,
       $m$Ja/Nein: Ist die Phase „Planung“ (§ 5.3, S. 40) abgeschlossen? DWA-M 820-3 § 6.3 (S. 14): „Die Phase „Planung“ enthält die Projektschritte von der Grundlagenermittlung bis zur Einreichung der Genehmigungsunterlagen, einschließlich Rückfragen der Genehmigungsbehörden und die Erteilung der Genehmigungen, Bewilligungen und Erlaubnisse.“ Das Datum dieser Planungsphasen-Zusammenfassung (planning_summary_date) gibt es erst, wenn die Phase abgeschlossen ist. Nein = Phase noch nicht abgeschlossen: das Datum ist ausgeblendet. Ja: das Datum wird gefragt. Die übrigen Fragen dieses Blatts (abgeschlossene Leistungsphasen, Planungs-Meilensteine, Kostenermittlung, Genehmigungen) bleiben sichtbar und werden mit dem aktuellen Stand beantwortet. An diese Frage ist keine Prüfung gebunden. Ist die Phase abgeschlossen, die Antwort auf Ja setzen und das Blatt erneut zur Freigabe einreichen. Bis dahin führen die Unterlagen die Phase unter „Phasen noch nicht erreicht bzw. noch nicht abgeschlossen“ auf; an sie ist keine Prüfung gebunden. Unbeantwortet bleibt das Datum sichtbar. Werkzeug-Frage; Phase im Sinne von DWA-M 820-3 § 2.1 (S. 8): „bestimmter Abschnitt des gesamten Projektablaufs, der einen eindeutigen Beginn und ein definiertes Ende aufweist“.
[EN] Yes/No: is the phase "planning" (§ 5.3, p. 40) completed? DWA-M 820-3 § 6.3 (p. 14): "the phase "planning" contains the project steps from the establishment of the basis up to the submission of the permit documents, including queries of the permit authorities and the granting of the permits, approvals and authorisations." The date of this planning-phase summary (planning_summary_date) exists only once the phase is completed. No = phase not completed yet: the date is hidden. Yes: the date is asked. The other questions of this sheet (completed service phases, planning milestones, cost estimation, permits) stay visible and are answered with the current status. No check is tied to this question. When the phase is completed, set the answer to Yes and submit the sheet for approval again. Until then the documents list the phase under "phases not yet reached or not yet completed"; no check is tied to it. Unanswered, the date stays visible. Tool question; phase in the sense of DWA-M 820-3 § 2.1 (p. 8): "a specific section of the entire project sequence that has a clear beginning and a defined end".$m$,
       'imported_unverified', $m$DWA-M 820-3 § 6.3 (S. 14): „Die Phase „Planung“ enthält die Projektschritte von der Grundlagenermittlung bis zur Einreichung der Genehmigungsunterlagen, einschließlich Rückfragen der Genehmigungsbehörden und die Erteilung der Genehmigungen, Bewilligungen und Erlaubnisse.“ DWA-M 820-3 § 2.1 (S. 8): „bestimmter Abschnitt des gesamten Projektablaufs, der einen eindeutigen Beginn und ein definiertes Ende aufweist“$m$, $m$DWA-M 820-2 §5.3 Z.1116 (PDF S. 42) + DWA-M 820-3 §6.3 Z.427 (PDF S. 16) + DWA-M 820-3 §2.1 Z.219 (PDF S. 10)$m$, NULL, NULL, NULL, NULL, 0, true
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE s.code = 'DWA-M-820-2' AND w.code = '820-2-15'
   AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'phase_planung_abgeschlossen')
RETURNING *)
INSERT INTO m820_c4p_written (tbl, id, md5) SELECT 'fields_new', ins.id, md5(row_to_json(ins)::text) FROM ins;
-- NEW DWA-M-820-2 820-2-19 phase_vergabe_abgeschlossen (boolean, required, section B, visible_when bauleistungen_vergeben == true)
WITH ins AS (
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, visible_when, consumer_worksheets, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'phase_vergabe_abgeschlossen', $m$Phase „Vorbereitung und Durchführen der Vergabe“ abgeschlossen (Aufträge an die ausführenden Firmen erteilt)$m$, $m$Phase "preparation and conduct of the award" completed (contracts awarded to the executing firms)$m$, 'boolean', NULL, true, $m$§5.5; DWA-M 820-3 §6.4$m$,
       $m$Ja/Nein: Ist die Phase „Vorbereitung und Durchführen der Vergabe“ (Bauleistungen) (§ 5.5, S. 47) abgeschlossen, sind also die Aufträge an die ausführenden Firmen erteilt? DWA-M 820-3 § 6.4 (S. 15): „Die Ausführungsvorbereitung beginnt mit der Ausführungsplanung, beinhaltet die Vorbereitung der Vergabe, und endet mit der Auftragserteilung an die ausführenden Unternehmen.“ Phasenziel (S. 16): „Die ausführenden Unternehmen sind bestimmt, die Vergaben sind erfolgt.“ Die Vergabe-Zusammenfassung dieses Blatts (Vergabeverfahren, Auswahlentscheidung, Zuschlagsdatum, endgültiger Auftragswert, Datum der Zusammenfassung) gibt es erst danach. Nein = Phase noch nicht abgeschlossen: die fünf Angaben sind ausgeblendet. Ja: sie werden gefragt. Nur sichtbar, wenn Bauleistungen an ausführende Firmen vergeben werden (bauleistungen_vergeben = Ja, 820-2-17). An diese Frage ist keine Prüfung gebunden. Ist die Phase abgeschlossen, die Antwort auf Ja setzen und das Blatt erneut zur Freigabe einreichen. Bis dahin führen die Unterlagen die Phase unter „Phasen noch nicht erreicht bzw. noch nicht abgeschlossen“ auf; an sie ist keine Prüfung gebunden. Unbeantwortet bleiben die Angaben sichtbar. Werkzeug-Frage; Phase im Sinne von DWA-M 820-3 § 2.1 (S. 8): „bestimmter Abschnitt des gesamten Projektablaufs, der einen eindeutigen Beginn und ein definiertes Ende aufweist“.
[EN] Yes/No: is the phase "preparation and conduct of the award" (construction works) (§ 5.5, p. 47) completed, i.e. are the contracts awarded to the executing firms? DWA-M 820-3 § 6.4 (p. 15): "the preparation of execution begins with the execution planning, includes the preparation of the award, and ends with the award of the contracts to the executing companies." phase goal (p. 16): "the executing companies are determined, the awards have taken place." The award summary of this sheet (award procedure, selection decision, award date, final contract value, date of the summary) exists only after that. No = phase not completed yet: the five entries are hidden. Yes: they are asked. Shown only when construction works are awarded to executing firms (bauleistungen_vergeben = yes, 820-2-17). No check is tied to this question. When the phase is completed, set the answer to Yes and submit the sheet for approval again. Until then the documents list the phase under "phases not yet reached or not yet completed"; no check is tied to it. Unanswered, the entries stay visible. Tool question; phase in the sense of DWA-M 820-3 § 2.1 (p. 8): "a specific section of the entire project sequence that has a clear beginning and a defined end".$m$,
       'imported_unverified', $m$DWA-M 820-3 § 6.4 (S. 15): „Die Ausführungsvorbereitung beginnt mit der Ausführungsplanung, beinhaltet die Vorbereitung der Vergabe, und endet mit der Auftragserteilung an die ausführenden Unternehmen.“ Phasenziel (S. 16): „Die ausführenden Unternehmen sind bestimmt, die Vergaben sind erfolgt.“ DWA-M 820-3 § 2.1 (S. 8): „bestimmter Abschnitt des gesamten Projektablaufs, der einen eindeutigen Beginn und ein definiertes Ende aufweist“$m$, $m$DWA-M 820-2 §5.5 Z.1384 (PDF S. 49) + DWA-M 820-3 §6.4 Z.451 (PDF S. 17) + DWA-M 820-3 §6.4 Z.476 (PDF S. 18) + DWA-M 820-3 §2.1 Z.219 (PDF S. 10)$m$, NULL, NULL, $m$bauleistungen_vergeben == true$m$, NULL, 0, true
