   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type, md5(coalesce(f.verification_quote,'')), coalesce(f.source_anchor,''))) = '105614c1bc4d32b370db1b915ce0b7d4';
-- DWA-M-820-2 820-2-16 permit_conditions_tracked: visible_when, description, verification_quote, source_anchor — visible_when auflagen_count >= 1
INSERT INTO fields_archive_m820_c4p SELECT f.* FROM fields f, worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-16' AND f.symbol = 'permit_conditions_tracked' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type, md5(coalesce(f.verification_quote,'')), coalesce(f.source_anchor,''))) = '2771ae2e189a8419a81b74f47b4e3e1a'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_c4p a WHERE a.id = f.id);
UPDATE fields f
   SET visible_when = $m$auflagen_count >= 1$m$,
       description = $m$Bestätigt, dass alle wasserrechtlichen/Bau-/Umwelt-Auflagen verfolgt werden. §5.4.5 (Ziel): "Die von den Behörden erteilten Auflagen werden vollständig und sorgfältig beachtet." Nur sichtbar, wenn im Register der Auflagen aus Genehmigungen (auflagen, dieses Blatt) mindestens eine Auflage erfasst ist (auflagen_count ≥ 1) – § 5.4.5 (S. 47): „Eine aktive Nachverfolgung der Auflagen findet statt und hilft dabei, die Erledigung der Auflagen zu den erforderlichen Zeitpunkten nachweisen zu können.“ Ohne erteilte Auflage gibt es nichts zu verfolgen; REQ-37 gilt dann nicht. Ein leer gespeichertes Register zählt als „keine Auflage“; solange das Register nie gespeichert wurde, bleibt die Frage sichtbar.
[EN] Confirms all water-law/construction/environmental conditions are tracked. §5.4.5 (target state): "the conditions imposed by the authorities are observed fully and carefully." Shown only when at least one condition is recorded in the register of conditions from permits (auflagen, this sheet; auflagen_count ≥ 1) – § 5.4.5 (p. 47): "an active follow-up of the conditions takes place and helps to be able to prove the completion of the conditions at the required points in time." Without an imposed condition there is nothing to follow up; REQ-37 then does not apply. A register saved empty counts as "no condition"; as long as the register was never saved, the question stays visible.$m$,
       verification_quote = $m$Sichtbarkeitsregel / visibility rule (visible_when): § 5.4.5 (S. 47): „Eine aktive Nachverfolgung der Auflagen findet statt und hilft dabei, die Erledigung der Auflagen zu den erforderlichen Zeitpunkten nachweisen zu können.“$m$,
       source_anchor = $m$DWA-M 820-2 §5.4.5 Z.1380 (PDF S. 49) — visible_when$m$
