-- DWA-M-820-2 820-2-09 REQ-16 (block, stays block): condition, description
INSERT INTO compliance_requirements_archive_m820_c4p SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND cr.code = 'REQ-16'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'c878af5ceae882134b77219b67d2ae68'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_c4p a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF phase_auftrag_erteilt == true THEN (contract_amendments_tracked == true)$m$,
       description = $m$Blockiert, bis contract_amendments_tracked bestätigt ist. §4.6.1: Verträge werden bei Leistungsänderungen nachvollziehbar fortgeschrieben. Gilt erst, wenn der Auftrag an den Auftragnehmer erteilt ist (phase_auftrag_erteilt = Ja, dieses Blatt) – § 4.6.1 (S. 32 f.): „Ein Vertrag wird geschlossen, bei dem Änderungen nachvollziehbar fortgeschrieben werden, sodass jeder, der in das Projekt einsteigt, klar erkennen kann, was vertraglich vereinbart wurde.“ Vorher (phase_auftrag_erteilt = Nein) gilt die Prüfung noch nicht; ohne Antwort wartet sie (sperrt) und nennt die Frage.
[EN] Blocks until contract_amendments_tracked is confirmed. §4.6.1: contracts are traceably updated whenever the scope of services changes. Applies only once the contract with the planner / engineering office is concluded (phase_auftrag_erteilt = yes, this sheet) – § 4.6.1 (pp. 32 f.): "a contract is concluded in which changes are traceably updated, so that anyone who joins the project can clearly see what was contractually agreed." Before that (phase_auftrag_erteilt = no) the check does not apply yet; unanswered, it waits (blocks) and names the question.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND cr.code = 'REQ-16'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'c878af5ceae882134b77219b67d2ae68';
-- DWA-M-820-2 820-2-09 REQ-17 (warn, stays warn): condition, description
INSERT INTO compliance_requirements_archive_m820_c4p SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND cr.code = 'REQ-17'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'a8d3d6fa476f1ce55ee3fe71ae0d3317'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_c4p a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF phase_auftrag_erteilt == true THEN (approval_procedure_defined == true)$m$,
       description = $m$Warnt (sperrt die Freigabe nicht), solange approval_procedure_defined (dieses Blatt) nicht bestätigt ist. § 4.6.2 (S. 33): „Nach jeder abgeschlossenen Leistungsphase erfolgt eine Freigabe der Planungsleistungen. Passend zum Projektablauf und zur Projektlaufzeit wird auch die Abnahme der Planungsleistungen geregelt.“ Gedruckt ist ein Zielbild im Indikativ ohne Modalverb (zweites Element des Qualitätsbausteins, Einleitung S. 11: „Darauf folgt das zweite Element, das sich mit der Zielsetzung und dem Optimierungspotenzial beschäftigt.“) – deshalb Warnung. Gilt erst, wenn der Auftrag an den Auftragnehmer erteilt ist (phase_auftrag_erteilt = Ja, dieses Blatt) – § 4.6.2 (S. 33): „Im Vertrag mit dem Auftragnehmer wird generell festgelegt, dass Teilabnahmen möglich sind.“ Vorher gilt die Warnung noch nicht.
[EN] Warns (does not block approval) while approval_procedure_defined (this sheet) is not confirmed. § 4.6.2 (p. 33): "after each completed service phase the planning work is released; acceptance of the planning work is also regulated to fit the project sequence and duration." What is printed is a target state in the indicative, without a modal verb (second element of the quality module, introduction p. 11: "then follows the second element, dealing with the objective and the optimisation potential") – hence a warning. Applies only once the contract with the planner / engineering office is concluded (phase_auftrag_erteilt = yes, this sheet) – § 4.6.2 (p. 33): "in the contract with the Auftragnehmer (planner) it is generally laid down that partial acceptances are possible." Before that the warning does not apply yet.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND cr.code = 'REQ-17'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = 'a8d3d6fa476f1ce55ee3fe71ae0d3317';
-- DWA-M-820-2 820-2-09 REQ-18 (warn, stays warn): condition, description
INSERT INTO compliance_requirements_archive_m820_c4p SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND cr.code = 'REQ-18'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '73a4516f12e5ed3c77c5f3c5f5c48829'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_c4p a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF phase_auftrag_erteilt == true THEN (quality_monitoring_active == true)$m$,
       description = $m$Warnt (sperrt die Freigabe nicht), solange quality_monitoring_active (dieses Blatt) nicht bestätigt ist. § 4.7.1 (S. 34): „Eine phasenbezogene Prüfung der Qualität der Ingenieurleistungen wird in einem Qualitätssicherungsplan festgelegt, der neben der Eigenüberwachung auch die Fremdüberwachung festlegt.“ Gedruckt ist ein Zielbild im Indikativ ohne Modalverb (zweites Element des Qualitätsbausteins, Einleitung S. 11: „Darauf folgt das zweite Element, das sich mit der Zielsetzung und dem Optimierungspotenzial beschäftigt.“) – deshalb Warnung. Gilt erst, wenn der Auftrag an den Auftragnehmer erteilt ist (phase_auftrag_erteilt = Ja, dieses Blatt) – § 4.7.1 (S. 34): „Die Qualitätsüberwachung der Planungsleistungen ist vertraglich nicht geregelt.“ Vorher gilt die Warnung noch nicht.
[EN] Warns (does not block approval) while quality_monitoring_active (this sheet) is not confirmed. § 4.7.1 (p. 34): "a phase-related check of the quality of the engineering services is laid down in a quality-assurance plan that sets out third-party monitoring besides self-monitoring." What is printed is a target state in the indicative, without a modal verb (second element of the quality module, introduction p. 11: "then follows the second element, dealing with the objective and the optimisation potential") – hence a warning. Applies only once the contract with the planner / engineering office is concluded (phase_auftrag_erteilt = yes, this sheet) – § 4.7.1 (p. 34): "the quality monitoring of the planning services is not regulated by contract." Before that the warning does not apply yet.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND cr.code = 'REQ-18'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '73a4516f12e5ed3c77c5f3c5f5c48829';
-- DWA-M-820-2 820-2-09 REQ-19 (warn, stays warn): condition, description
INSERT INTO compliance_requirements_archive_m820_c4p SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND cr.code = 'REQ-19'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '6b52ba4903bb1f997ce4ab1bc5b799bc'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_c4p a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF verantwortung_lph8 != 'entfaellt' THEN (IF phase_auftrag_erteilt == true THEN (qs_plan_lph8_present == true))$m$,
       description = $m$Warnt (sperrt die Freigabe nicht), solange qs_plan_lph8_present (dieses Blatt) nicht bestätigt ist – nur solange LPH 8 stattfindet (820-2-01: verantwortung_lph8 ≠ entfällt). § 4.7.2 (S. 34): „Ein fundierter Qualitätssicherungsplan mit entsprechenden Arbeitsaufträgen und Dokumentationsfunktionen wird gemeinsam erstellt und aktiv umgesetzt.“ Gedruckt ist ein Zielbild im Indikativ ohne Modalverb (zweites Element des Qualitätsbausteins, Einleitung S. 11: „Darauf folgt das zweite Element, das sich mit der Zielsetzung und dem Optimierungspotenzial beschäftigt.“) – deshalb Warnung. Gilt erst, wenn der Auftrag an den Auftragnehmer erteilt ist (phase_auftrag_erteilt = Ja, dieses Blatt) – § 4.7.2 (S. 34): „Im Auftragnehmerteam ist nicht geklärt, nach welchen Vorgaben und in welchem Umfang die Qualitätskontrolle der Bauleistungen erfolgt.“ Vorher gilt die Warnung noch nicht.
[EN] Warns (does not block approval) while qs_plan_lph8_present (this sheet) is not confirmed – only while LPH 8 takes place (820-2-01: verantwortung_lph8 ≠ does not occur). § 4.7.2 (p. 34): "a sound quality-assurance plan with corresponding work orders and documentation functions is jointly drawn up and actively implemented." What is printed is a target state in the indicative, without a modal verb (second element of the quality module, introduction p. 11: "then follows the second element, dealing with the objective and the optimisation potential") – hence a warning. Applies only once the contract with the planner / engineering office is concluded (phase_auftrag_erteilt = yes, this sheet) – § 4.7.2 (p. 34): "in the Auftragnehmer (planner) team it is not clarified according to which specifications and to what extent the quality control of the construction works takes place." Before that the warning does not apply yet.$m$
