   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '6b52ba4903bb1f997ce4ab1bc5b799bc';
-- DWA-M-820-2 820-2-16 REQ-37 (warn, stays warn): condition, description
INSERT INTO compliance_requirements_archive_m820_c4p SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-16' AND cr.code = 'REQ-37'
   AND md5(concat_ws('|', coalesce(cr.condition,''), cr.severity, md5(coalesce(cr.description,'')), coalesce(cr.clause_reference,''))) = '4e6d4583e096e1649395faca525b844b'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_c4p a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF auflagen_count >= 1 THEN (permit_conditions_tracked == true)$m$,
       description = $m$Warnt (sperrt die Freigabe nicht), solange permit_conditions_tracked (dieses Blatt) nicht bestätigt ist. § 5.4.5 (S. 47): „Die von den Behörden erteilten Auflagen werden vollständig und sorgfältig beachtet.“ Gedruckt ist ein Zielbild im Indikativ ohne Modalverb (zweites Element des Qualitätsbausteins, Einleitung S. 11: „Darauf folgt das zweite Element, das sich mit der Zielsetzung und dem Optimierungspotenzial beschäftigt.“) – deshalb Warnung. Gilt nur, wenn im Register der Auflagen mindestens eine Auflage erfasst ist (auflagen_count ≥ 1, dieses Blatt) – § 5.4.5 (S. 47): „Eine aktive Nachverfolgung der Auflagen findet statt und hilft dabei, die Erledigung der Auflagen zu den erforderlichen Zeitpunkten nachweisen zu können.“ Ohne erteilte Auflage gibt es nichts zu verfolgen.
[EN] Warns (does not block approval) while permit_conditions_tracked (this sheet) is not confirmed. § 5.4.5 (p. 47): "the conditions imposed by the authorities are observed fully and carefully." What is printed is a target state in the indicative, without a modal verb (second element of the quality module, introduction p. 11: "then follows the second element, dealing with the objective and the optimisation potential") – hence a warning. Applies only when at least one condition is recorded in the register of conditions (auflagen_count ≥ 1, this sheet) – § 5.4.5 (p. 47): "an active follow-up of the conditions takes place and helps to be able to prove the completion of the conditions at the required points in time." Without an imposed condition there is nothing to follow up.$m$
  FROM worksheet_templates w, standards s
